import unittest


class TestAntiShuffle(unittest.TestCase):

    def test_single_word(self):
        self.assertEqual(anti_shuffle("hello"), "ehllo")

    def test_multiple_words(self):
        self.assertEqual(anti_shuffle("hello world"), "ehllo dorlw")

    def test_words_with_punctuation(self):
        self.assertEqual(anti_shuffle("Hello World!!!"), "Hello !!!Wdlor")

    def test_empty_string(self):
        self.assertEqual(anti_shuffle(""), "")

    def test_single_space(self):
        self.assertEqual(anti_shuffle(" "), " ")

    def test_multiple_spaces(self):
        self.assertEqual(anti_shuffle("a  b"), "a  b")

    def test_single_character_words(self):
        self.assertEqual(anti_shuffle("a b c"), "a b c")

    def test_case_sensitivity(self):
        # Uppercase letters sort before lowercase (ASCII order)
        self.assertEqual(anti_shuffle("bA"), "Ab")

    def test_numbers_in_words(self):
        self.assertEqual(anti_shuffle("a1b2"), "12ab")

    def test_already_sorted_word(self):
        self.assertEqual(anti_shuffle("abc"), "abc")

    def test_long_sentence(self):
        self.assertEqual(anti_shuffle("the quick brown fox"),
                         "ehn cikoq bnorw fox")

    def test_word_order_preserved(self):
        result = anti_shuffle("zebra apple")
        self.assertEqual(result.split(" ")[0], "aberz")
        self.assertEqual(result.split(" ")[1], "aelpp")

    def test_no_reordering_of_words(self):
        self.assertEqual(len(anti_shuffle("one two three").split(" ")), 3)


